/**
 * etymology.js — "why this character looks like this": a small mnemonic hint
 * (meaning part / sound part or a short story) under the radical decomposition
 * and on every stroke-sheet card.
 *
 * Data: `public/data/etymology/` (generated by scripts/build-etymology.mjs from
 * Make Me a Hanzi `dictionary.txt` — see CREDITS.md). One sharded JSON per
 * character, keyed by the character itself:
 *   { type: 'pictophonetic'|'ideographic'|'pictographic',
 *     hint?, semantic?, semanticGloss?, phonetic?, phoneticPinyin? }
 *
 * Public API (browser-free helpers, covered by tests/etymology.test.mjs):
 *   normalizeCharacter(value)             -> first CJK char or ''
 *   createEtymologyLoader({base, fetchImpl}) -> { load(char) }
 *   getEtymology(char)                    -> Promise<entry|null>
 *   formatEtymology(entry)                -> [{kind:'parts', items:[{key,params}]} |
 *                                             {kind:'hint', text}]
 *   renderEtymology(char, {doc})          -> Promise<HTMLElement|null> (small box)
 *
 * UI text comes from the `etymology.*` keys (src/locales/en.d/etymology.json).
 * Better no hint than a weird one: a character with neither hint nor
 * meaning/sound parts renders nothing (null).
 */
import { t } from './i18n.js';
import { h } from './dom.js';

/** Where the browser build serves the etymology shards from (next to `src/`). */
export const DEFAULT_ETYMOLOGY_BASE = new URL('../data/etymology/', import.meta.url);

const STYLE_ID = 'etymology-style';
// Kangxi radical (+ supplement) blocks are included on purpose: IDS parts and
// radical symbols (⺊, 氵 …) are looked up by the decomposition screens too.
const CJK_RE = /[\u2e80-\u2eff\u2f00-\u2fdf\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/u;

let fetcher = null;
let defaultLoader = null;

/** Inject a fetch implementation (Node tests, workers). Clears the cache. */
export function configure(opts = {}) {
  if (typeof opts.fetch === 'function') fetcher = opts.fetch;
  defaultLoader = null;
}

function getDefaultLoader() {
  if (!defaultLoader) defaultLoader = createEtymologyLoader();
  return defaultLoader;
}

/** First CJK character of a route segment / string (decodes, survives junk). */
export function normalizeCharacter(value) {
  if (value === undefined || value === null) return '';
  let text = String(value).trim();
  if (!text) return '';
  try { text = decodeURIComponent(text); } catch { /* malformed escape */ }
  const match = text.match(CJK_RE);
  return match ? match[0] : '';
}

/** Loader for `public/data/etymology/` (index + range shards). */
export function createEtymologyLoader({ base = DEFAULT_ETYMOLOGY_BASE, fetchImpl } = {}) {
  const root = toBaseUrl(base);
  const cache = new Map();

  const fetchJson = async (url) => {
    if (cache.has(url)) return cache.get(url);
    const pending = (async () => {
      if (fetchImpl) return fetchImpl(url);
      if (fetcher) return fetcher(url);
      const response = await fetch(url);
      if (!response.ok) throw new Error(`etymology: HTTP ${response.status} for ${url}`);
      return response.json();
    })();
    cache.set(url, pending);
    try { return await pending; }
    catch (error) { cache.delete(url); throw error; }
  };

  const load = async (character) => {
    const char = normalizeCharacter(character);
    if (!char) return null;
    const index = await fetchJson(new URL('index.json', root).href);
    const shards = index?.shards ?? [];
    const code = char.codePointAt(0);
    let lo = 0;
    let hi = shards.length - 1;
    let shardIdx = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      const range = shards[mid]?.range;
      if (!range || range.length < 2) break;
      if (code < range[0].codePointAt(0)) hi = mid - 1;
      else if (code > range[1].codePointAt(0)) lo = mid + 1;
      else { shardIdx = mid; break; }
    }
    if (shardIdx < 0) return null;
    const file = shards[shardIdx].file;
    const shard = await fetchJson(new URL(file, root).href);
    return shard?.[char] ?? null;
  };

  return { load };
}

/** Etymology of one character, or null when we have nothing for it. */
export const getEtymology = (character) => getDefaultLoader().load(character);

/**
 * Rendering plan for an entry — pure, no DOM, no i18n lookup (tests use it).
 * One block per row: a `parts` row (meaning/sound) and/or the `hint` story.
 */
export function formatEtymology(entry) {
  if (!entry || typeof entry !== 'object') return [];
  const blocks = [];
  if (entry.type === 'pictophonetic') {
    const items = [];
    if (entry.semantic) {
      items.push(entry.semanticGloss
        ? { key: 'etymology.meaningPart', params: { char: entry.semantic, gloss: entry.semanticGloss } }
        : { key: 'etymology.meaningPartNoGloss', params: { char: entry.semantic } });
    }
    if (entry.phonetic) {
      items.push(entry.phoneticPinyin
        ? { key: 'etymology.soundPart', params: { char: entry.phonetic, pinyin: entry.phoneticPinyin } }
        : { key: 'etymology.soundPartNoPinyin', params: { char: entry.phonetic } });
    }
    if (items.length) blocks.push({ kind: 'parts', items });
  }
  if (entry.hint) blocks.push({ kind: 'hint', text: entry.hint });
  return blocks;
}

const CSS = `
.etymology-hint { display: flex; flex-direction: column; gap: 0.2rem; margin: 0.4rem 0 0; padding: 0.5rem 0.6rem; border-left: 3px solid var(--accent, #b3261e); border-radius: 0.3rem; background: color-mix(in srgb, var(--line, #c9c4bd) 18%, transparent); font-size: 0.9rem; }
.etymology-hint p { margin: 0; }
.etymology-parts { font-weight: 600; }
.etymology-story { opacity: 0.85; }
@media (prefers-color-scheme: dark) {
  .etymology-hint { background: #221f1d; }
}
`;

function ensureStyles(doc) {
  if (doc.getElementById(STYLE_ID)) return;
  const style = doc.createElement('style');
  style.id = STYLE_ID;
  style.textContent = CSS;
  doc.head.append(style);
}

/**
 * Small DOM box for a character's etymology, or null when there is nothing to
 * show. The element carries `dataset.etymologyType` / `dataset.etymologyChar`
 * so a headless check can read it back.
 */
export async function renderEtymology(character) {
  const char = normalizeCharacter(character);
  if (!char || typeof document === 'undefined') return null;
  let entry = null;
  try { entry = await getEtymology(char); }
  catch (error) { console.error('etymology: load failed', error); return null; }
  const blocks = formatEtymology(entry);
  if (!blocks.length) return null;
  ensureStyles(document);
  const node = document.createElement('div');
  node.className = 'etymology-hint';
  node.dataset.etymologyChar = char;
  node.dataset.etymologyType = entry.type;
  for (const block of blocks) {
    if (block.kind === 'hint') {
      node.append(h('p', { class: 'etymology-story', text: block.text }));
    } else {
      node.append(h('p', {
        class: 'etymology-parts',
        text: block.items.map((item) => t(item.key, item.params)).join(' · '),
      }));
    }
  }
  return node;
}

function toBaseUrl(base) {
  if (base instanceof URL) return base;
  const text = String(base ?? DEFAULT_ETYMOLOGY_BASE.href);
  try { return new URL(text); }
  catch { return new URL(text.endsWith('/') ? text : `${text}/`, DEFAULT_ETYMOLOGY_BASE); }
}
